    found = (CThingVillage*)&g_things[0];
    if (CThingSearchToolsMethods().GetPBestLeafThing(filter, compare, &found) || found != 0) bad = 1;
    if (bad) { std::printf("0048cb50_TEST FAIL\n"); return 1; }
    std::printf("0048cb50_TEST PASS\n");
    return 0;
}

