    CThingFilter_AICreatureHasProperty p = { 3 };
    CFilter_Bind2<std::unary_negate<CThingFilter_HasScriptedControl>, CThingFilter_AICreatureHasProperty> filter = { s, p };
    CThingCompare_Nearest compare = { { 11.0f, 0.0f, 0.0f } };
    CThingAICreature* found = 0;
