    const CThing* want = 0;
    for (i = 0; i < N; ++i) {
        const CThing& t = g_things[i];
        if (g_things[i].IsIncludedInThingScans() && (!(t.Attr & 0x10) && (t.Attr & 0x20)) && (!want || Dist(&g_things[i], 11.0f) < Dist(want, 11.0f)))
